#include <bits/stdc++.h>
using namespace std;

int main() {
	// your code goes here
    int t;
    cin>>t;
    while(t--){
        int n;
        cin>>n;
        vector<long long>rating(3*n);
        for(int i=0;i<3*n;i++){
            cin>>rating[i];
        }
        sort(rating.begin(),rating.end(),greater<long long>());
        vector<long long>temp((3*n)+1);
        long long largest=0;
        for(int i=0;i<(3*n);i++){
            temp[i+1]=temp[i]+rating[i];
        }
        for(int i=0;i<=n;i++){
            long long s=2*temp[i];
            int remaining=n-i;
            int currsum=(3*n)-2*i;
            int left=0;
            int right=remaining;
            
            while(left<right){
                int mid=(left+right)/2;
                long long x=temp[i+2*mid]+3*temp[currsum-mid];
                long long y=temp[i+2*(mid+1)]+ 3*temp[currsum-mid-1];
                if(y>x){
                    left=mid+1;
                }
                else{
                    right=mid;
                }
            }
            long long ans=temp[i+2*left]+3*temp[currsum-left];
            largest=max(largest,s+ans);
        }
        cout<<largest<<endl;
        
        
    }
}
